var _VOCAL_RE = /^(?:a+h+|aa+h*|u+g*h+|uh+|u+n+|h+m+|m{2,}|n{2,}g*h*|(?:h[aeio]){2,}h*|ha{2,}h*|h+a+h+|k+h+|g+h+|ngh+|o{2,}h*|oo+h+|oh{2,}|hn+|a+n+)$/i;
