var _NOT_SPEAKER = /^(?:NOTE|WARNING|CAUTION|ATTENTION|TIME|TITLE|SIGN|TEXT|NEXT|EPISODE|TL|TN|PS)$/;
function _dropCaptionLines(text) {
  const out = [];
  const lines = String(text).split("\n");
  const isLabel = function (inner) {
    const s = inner.trim();
    return !!s && !/[.,!?…:]/.test(s) && s.split(/\s+/).length <= 3;   // 짧고 문장부호 없는 괄호만 효과음/화자 라벨로 본다
  };
  const head = /^[\[(（［]([^\[\]()（）［］\n]{1,24})[\])）］]\s*/;
  const tail = /\s*[\[(（［]([^\[\]()（）［］\n]{1,24})[\])）］]$/;
  for (let li = 0; li < lines.length; li++) {
    let v = lines[li].trim();
    if (!v) continue;
    if (/[♪♫♬♩]/.test(v)) continue;                         // ♪ 가사
    let m;
    while ((m = head.exec(v)) && isLabel(m[1])) v = v.slice(m[0].length);        // (laughs) 대사 / [Yuki] 대사
    while ((m = tail.exec(v)) && isLabel(m[1])) v = v.slice(0, m.index);         // 대사 (sniffs)
    v = v.trim();
    const sp = /^([A-Z][A-Z0-9 .'-]{0,20}):\s+/.exec(v);                         // SAKURA: 대사 (NOTE: 같은 머리말은 유지)
    if (sp && !_NOT_SPEAKER.test(sp[1].trim())) v = v.slice(sp[0].length).trim();
    if (!/[A-Za-z0-9]/.test(v)) continue;                                        // 남은 글자가 없음
    const words = v.split(/[\s,.!?…~-]+/).filter(Boolean);
    if (words.length && words.every(function (w) { return _VOCAL_RE.test(w); })) continue;   // 신음·비명
    out.push(v.replace(/\s{2,}/g, " "));
  }
  return out.join("\n");
}
